  Origen = Sql.Database("wdbanal-dwhp01.hdicolombia.com.co", "Liberty", [Query = "#(lf) SELECT TABLA1.*#(lf),TABLA2.TRESPUE#(lf),TABLA3.CMATRIC#(lf),TABLA5.OFICINA_FUSION#(lf)FROM (#(lf)SELECT a.[SSEGURO]#(lf),a.[RAMO_PROD]#(lf),a.[PERIODO_CONTABLE]#(lf),a.[SBU]#(lf),a.[USUARIO_MOV]#(lf),a.[INTERMEDIARIO_LIDE]#(lf),a.[SUCURSAL_PROD]#(lf),a.NRO_IDENTIFI_TOM#(lf),a.FI_CERTIFICADO#(lf),a.FF_CERTIFICADO#(lf),a.FECHA_EXPE#(lf),a.FI_ANEXO#(lf),a.[POLIZA]#(lf),a.certificado#(lf),a.RECIBO#(lf),SUM(a.[VR_PRIMA_MN_ORIG]) AS VR_PRIMA_MN_ORIG,#(lf)(SUM(a.[VR_PRIMA_PESOS_COA])) AS VR_PRIMA_PESOS_COA,#(lf)a.[TIPO_TRANSAC]#(lf),COD_TRANSAC#(lf),ALTURA_POLIZA#(lf),a.COD_MODALIDAD#(lf),a.frec_pago#(lf),CASE#(lf)when a.sucursal_prod = 177 and a.ramo_prod = '900753' then 'COOMEVA'#(lf)when a.sucursal_prod = 233 then 'RCI'#(lf)when a.sucursal_prod = 226 then 'CREDIORBE'#(lf)when a.sucursal_prod = 214 and a.ramo_prod = '900753' then 'BANCO DE OCCIDENTE'#(lf)when a.sucursal_prod in (200,230,231) and ramo_prod in ('900753','6041','6042','6045','6046','6047','6049') then 'OTROS BANCOS'#(lf)WHEN a.RAMO_PROD IN ('6039') and [SUCURSAL_PROD] not in (177,200,214,230,231,226) THEN 'PESADOS INDIVIDUAL'#(lf)WHEN a.RAMO_PROD IN ('6038','6046') and a.[SUCURSAL_PROD] not in (177,200,214,230,231,226) THEN 'TAXIS'#(lf)WHEN a.RAMO_PROD IN ('6047','6049') and a.[SUCURSAL_PROD] not in (177,200,214,230,231,226) THEN 'PESADOS COLECTIVO'#(lf)WHEN a.RAMO_PROD IN ('6041','6042','6045','900753') and a.[SUCURSAL_PROD] not in (177,200,214,230,231,226) THEN 'LIVIANOS'#(lf)ELSE 'PRIVATE'#(lf)END as SEGMENTO#(lf),CASE  #(lf)   WHEN t3.RAZON_SOCIAL=''#(lf)   THEN concat(TRIM(t3.NOMBRE_1),' ',TRIM(t3.NOMBRE_2),' ',TRIM(t3.APELLIDO_1),' ',TRIM(t3.APELLIDO_2))#(lf)   ELSE t3.RAZON_SOCIAL#(lf)END NOMBRE_TOM#(lf),FCONTABILIZACION#(lf),FADMINISTRACION#(lf)FROM [Liberty].[PROD].[DWH_POLIZAS_H] a--,#(lf)#(lf) #(lf)#(lf)left join (#(lf)select razon_social,nombre_1,nombre_2,apellido_1,min(APELLIDO_2) APELLIDO_2, NRO_UNICO_PERSONA#(lf)from [Liberty].[CLIENTE].[dwh_cliente_unico]#(lf)group by razon_social,nombre_1,nombre_2,apellido_1,NRO_UNICO_PERSONA#(lf)) t3 on a.NRO_UNICO_TOMADOR=t3.NRO_UNICO_PERSONA#(lf)WHERE#(lf)PERIODO_CONTABLE >= 202501#(lf)AND PERIODO_CONTABLE <= CONVERT(VARCHAR(6), GETDATE(), 112)#(lf)and SBU = 'AUT'#(lf)GROUP BY SSEGURO#(lf),RAMO_PROD,PERIODO_CONTABLE#(lf),a.SBU,NRO_IDENTIFI_TOM#(lf),FI_CERTIFICADO#(lf),FF_CERTIFICADO#(lf),SBU#(lf),INTERMEDIARIO_LIDE#(lf),a.FECHA_EXPE#(lf),SUCURSAL_PROD,#(lf)POLIZA#(lf),certificado#(lf),TIPO_TRANSAC#(lf),COD_TRANSAC#(lf),ALTURA_POLIZA#(lf),COD_MODALIDAD#(lf),SEGMENTO#(lf),a.FI_ANEXO#(lf),a.frec_pago#(lf),a.RECIBO,#(lf)t3.RAZON_SOCIAL#(lf),t3.NOMBRE_1#(lf),t3.NOMBRE_2#(lf),t3.APELLIDO_1#(lf),t3.APELLIDO_2#(lf),a.[USUARIO_MOV]--,NOMBRE_CLIENTE,)#(lf),FCONTABILIZACION#(lf),FADMINISTRACION#(lf)) AS TABLA1#(lf)LEFT JOIN #(lf)(#(lf)SELECT *#(lf)FROM(#(lf)SELECT a.sseguro#(lf), a.cpregun#(lf), a.crespue#(lf), a.nmovimi#(lf), b.trespue #(lf), ROW_NUMBER() over(partition by a.sseguro order by a.nmovimi desc) as indice#(lf)FROM liberty.axis.pregunpolseg a #(lf)left join liberty.axis.respuestas b on a.cpregun = b.cpregun and a.crespue = b.crespue and b.cidioma = 8 #(lf)where a.cpregun = 4790 #(lf)) as T0#(lf)where indice = 1#(lf)) AS TABLA2 #(lf)ON tabla1.sseguro = tabla2.sseguro#(lf)LEFT JOIN#(lf)(#(lf)SELECT *#(lf)FROM(#(lf)SELECT SSEGURO#(lf),NMOVIMI#(lf), CMATRIC#(lf), ROW_NUMBER() OVER(PARTITION BY SSEGURO ORDER BY NMOVIMI DESC ) AS INDICE#(lf)FROM LIBERTY.AXIS.AUTRIESGOS#(lf)) AS T1 #(lf)WHERE INDICE=1#(lf)) AS TABLA3#(lf)ON TABLA1.SSEGURO = TABLA3.SSEGURO#(lf)left join [Liberty].[AS400].[MAESTRO_INTERMEDIARIOS] AS TABLA4  #(lf)on (TABLA1.intermediario_lide=TABLA4.interm)#(lf)left join LIBERTY.APOYO.DWH_REDCOMERCIAL_SUCURSAL AS TABLA5#(lf)On TABLA4.SUCURSAL = TABLA5.SUCURSAL#(lf)OPTION(maxdop 0)#(lf)#(lf)"])
